struct ExtImageCopyCaptureCursorSessionV1Sink {
mut:
	proxy    ExtImageCopyCaptureCursorSessionV1
	listener ExtImageCopyCaptureCursorSessionV1Listener = NoopExtImageCopyCaptureCursorSessionV1Listener{}
}

fn (mut s ExtImageCopyCaptureCursorSessionV1Sink) on_event(msg &wayland.Message) !bool {
	match msg.opcode {
		0 {
			s.listener.enter(s.proxy)
		}
		1 {
			s.listener.leave(s.proxy)
		}
		2 {
			x := msg.arg_int(0)!
			y := msg.arg_int(1)!
			s.listener.position(s.proxy, x, y)
		}
		3 {
			x := msg.arg_int(0)!
			y := msg.arg_int(1)!
			s.listener.hotspot(s.proxy, x, y)
		}
		else {
			return false
		}
	}
	return true
}

