pub fn (proxy &ExtImageCopyCaptureCursorSessionV1) set_listener(listener ExtImageCopyCaptureCursorSessionV1Listener) ! {
	proxy.conn.set_sink(proxy.id, ExtImageCopyCaptureCursorSessionV1Sink{
