	proxy.conn.register_object(session_id, 'ext_image_copy_capture_session_v1', &ext_image_copy_capture_session_v1_desc)!
	proxy.conn.request(proxy.id, 1, [wayland.ArgValue(wayland.ObjectRef{ id: session_id })])!
	return ExtImageCopyCaptureSessionV1{
		Object: session_object
	}
}

